T[354660]="Una página arrancada del Codex of Secrets."
T[355165]="Varitas como esta, talladas con la forma de una estrella oscura, se entregaban a los sirvientes más leales de la reina Sybell. Solo una ha sobrevivido todos estos años, pero Stromgarde parece bastante feliz de desprenderse de ella..."
T[355168]="Antes del ataque de la Horda, las fuerzas de Stromgarde utilizaban ballestas como esta para eliminar a las fuerzas del Sindicato que deambulaban a la vista del puente."
T[355178]="Una creación experimental del Artífice Baraal, fabricada para proteger al portador contra compulsiones mentales."
T[355199]="No estás seguro de qué tipo de carne es exactamente, y no estás seguro de querer saberlo."
T[358721]="El bumerán perdido del capitán Dubi."
T[375250]="Obtenidas solo mediante tus hazañas, estas runas potencian tu progresión y personalización. Recógelas en abundancia en todas tus aventuras."
T[383080]="Se usan para aprender nuevas habilidades; estas se obtienen periódicamente a medida que subes de nivel."
T[383081]="Se usan para aprender y subir de nivel los talentos; estos se obtienen una vez por nivel tras el nivel 10."
T[383082]="Te otorga el poder de purgar y restablecer tus habilidades"
T[383083]="Te otorga el poder de purgar y restablecer tus talentos"
T[400064]="Conjunto inicial de Paladín de la Alianza"
T[400271]="Te enseña a invocar esta montura."
T[400750]="Se obtiene en las bandas de Classic. Te permite comprar equipo a Romus the Redeemer, que se encuentra en las ciudades principales. Los guardias pueden indicarte dónde está Romus."
T[401163]="Conjunto inicial de guerrero de la Alianza"
T[405728]="Un conjunto cosmético destinado a ser usado con la Transfiguración. Puedes ver cómo son los conjuntos cosméticos en la Colección de vanidad. Estos pueden obtenerse de otros jugadores, la casa de subastas o la tienda de la Ascensión."
T[410051]="Algo en esta hoja no se siente bien..."
T[410085]="Sientes una presencia reconfortante, pero fría."
T[410160]="¿A quién vas a llamar? ¡A la Cruzada!"
T[415004]="¿Eh? De verdad que NO les gusta el fuego."
T[415026]="Nadie llegará jamás a esto..."
T[415049]="Un solo soplo y jurarás que el tiempo se ralentiza. Lo llaman trance de polvo. Yo lo llamo decisiones de vida lamentables."
T[415052]="Perdido en una batalla, un abalorio de la codicia pirata olvidada."
T[415054]="El ejemplar más exquisito."
T[415059]="Puedes oír débilmente el mar cuando te acercas el oído."
T[415065]="Se recomienda supervisión parental - Contenido explícito"
T[415093]="No muchos sobreviven a ello."
T[415151]="Probablemente no deberías pensar en su uso anterior."
T[415160]="Imbuida con el poder resonante de los rituales de atadura de tierra de Martuk, esta capucha resuena con cada encantamiento, llamando a la roca y la piedra para que se levanten ante tu mandato."
T[420039]="Un conjunto cosmético destinado a ser usado con la Transfiguración. Puedes ver cómo son los conjuntos cosméticos en la Colección de vanidad. Estos pueden obtenerse de otros jugadores, la casa de subastas o la tienda de la Ascensión."
T[421527]="Incluye los siguientes objetos:\n\n - Tabardo morado hecho a medida\n - Bufanda de plumas de caminante\n - Capa de plumas de caminante"
T[421531]="Ligeramente crujiente. Completamente inútil."
T[426758]="Tomada de un gnomo muy enfadado"
T[450244]="¡Para talar árboles!"
T[450263]="Una varita esculpida a partir de otro hueso de Galgosh."
T[450264]="No lo compartas con tus seres queridos."
T[450512]="Quien corte la cuerda, tendrá que ir a vaciar el cubo."
T[450515]="Todavía brilla con veneno."
T[450521]="¡Las cavidades pueden enfurecer a cualquiera, sin duda!"
T[450525]="Las leyendas hablan de un pico solitario donde los relámpagos caen con la precisión de un reloj, una vez con cada luna llena. \n\nLa madera de la varita se tomó de un árbol alcanzado no una, sino dos veces; su poder está ahora entretejido en esta reliquia del antiguo linaje de los Thunderfalls."
T[450526]="Armas que te protegen de forma fiable de los bandidos... Casi siempre."
T[450528]="Tú... te... llevaste... ¿la vela?"
T[450551]="Ojalá hubiera podido llegar a esa última isla. Los peces siempre son más grandes al otro lado."
T[450552]="¿Soy un minero con suerte o qué?"
T[450559]="Estas notas describen la caída de un Drone hacia la locura mientras era objeto de experimentos."
T[450584]="Amor loco."
T[450616]="Snagglerspear es infame por usar este silbato en las cacerías de kodos, a menudo soplándolo para dar la señal a su manada para atacar."
T[450641]="Oyes un grito tenue que proviene de la espada."
T[450644]="Mankrik ya ha perdido suficiente... Quizá sea mejor volver a guardar esto."
T[450807]="Una rama de Bathran, un treant mágico que pagó el precio de los experimentos de los Renegados en la zona."
T[450809]="A nadie le gustan las caries."
T[450871]="¿Deberías estar tocando esto?"
T[451046]="Un fragmento brillante, contaminado por energía de la Legión."
T[451047]="Contiene apenas una pizca del poder de Aessina."
