T[509902]="Te enseña a invocar esta montura."
T[509903]="¡Sigue esta sencilla guía de 1 pasos y te convertirás instantáneamente en un flexer famoso!"
T[515031]="Comer esto te matará... Eso es todo."
T[515037]="Grabado con runas malignas."
T[515039]="Olvidado hace mucho tiempo."
T[515046]="Sorprendentemente resistente, se ajusta bastante bien cuando se enrolla como un cordón y se ata a la cintura."
T[515047]="No estoy muy seguro de dónde ha estado esto."
T[515150]="Esta mano grabada con runas parece apartar las hojas."
T[515208]="Permaneció en el fuego un poco más de lo habitual."
T[515216]="Al final, a veces el único plan que queda es huir."
T[515222]="Templado en la llama viviente."
T[515223]="Endurecido por las llamas que antaño desafió."
T[515251]="El amor y el calor van de la mano."
T[515273]="Directamente de la colección de herramientas del Overseer Maltorius. Con esto se construyeron los primeros gólems que iniciaron este sitio de excavación. A veces, parece que sirve para algo más que una herramienta."
T[515284]="Las runas del cinturón pulsan con el poder de una era olvidada hace mucho tiempo."
T[515286]="Armadura forjada para una batalla de hace mucho tiempo."
T[515292]="La basura de un hombre..."
T[515365]="Vibra con la misma frecuencia que los Pilones."
T[515382]="Esta arma arrojadiza fue una vez parte de una colección de Fab Four. No dejes que el juego de palabras te engañe. Sigue pegando como un golpe digno de una gira mundial."
T[515531]="Sostenido en tu mano, emite un suave zumbido, puntuado por un tenue chasquido. Quizá sea mejor dejarlo en paz."
T[515537]="Aumenta la velocidad de carrera un 300%"
T[515603]="Tallado en el cuerpo de un Caminante de los acantilados. A juzgar por el destino de los furbolgs, los gigantes no estaban muy contentos con esto."
T[515604]="Un suave y melódico zumbido resuena desde esta lira antigua. No puedes evitar preguntarte cómo ha permanecido intacta todos estos años..."
T[515608]="Con algo de esfuerzo, por fin has podido quitar este sello de la antigua estatua."
T[515621]="Una imitación de un anillo mucho más poderoso perdido hace mucho tiempo."
T[515623]="Una representación metafórica de la fuerza de Azshara; su poder parece ser también bastante literal."
T[515624]="Eldara inscribía runas de Beth'Amara en cristales como este para proteger la ciudad, pero ni siquiera ese poder fue suficiente para salvarla del Sundering."
T[515625]="Eldara inscribía runas Markri en armas como esta para defender la ciudad de los atacantes. Los encantamientos que la animaban se desvanecieron hace mucho tiempo, pero parece funcionar de forma similar a una ballesta moderna."
T[515626]="Estas hombreras portan un tenue eco del poder del Sumo Sacerdote Zin-Malor, un enigma que sigue desconcertando a los historiadores."
T[515629]="¡Estas tierras llevan el nombre de Su Resplandor, y en su nombre las reclamaremos!"
T[515634]="Las runas grabadas en este bastón aún brillan con el poder de un antiguo escriba que desapareció de Azeroth hace mucho tiempo."
T[515676]="Ingeniería goblin: ¡Recuerda, solo tiene que funcionar una vez!"
T[515681]="Forjado con hierro de granja y bendecido por granjeros fieles"
T[515703]="Queda poco del cuerpo que una vez vistió estas almohadillas, pero la magia persistente tejida en la tela hecha jirones aún perdura."
T[515720]="Arañado por dientes y garras, este humilde anillo cuenta la historia final de un cazador que nunca regresó de la naturaleza."
T[515733]="Resuena con el tenue latido de un mal antiguo."
T[515737]="Un manual maltrecho con secciones enteras tachadas y sustituidas por «-50 DKP!» en tinta roja y negrita."
T[515791]="La magia de las Cavernas se ha filtrado profundamente en la madera, haciendo que emita un zumbido con un poder silencioso y eterno."
T[515827]="Cumple su función."
T[515835]="¡Cuidado, la lente está rota, no te metas cristales en los ojos!"
T[515839]="¡Confianza cosmética!"
T[515844]="La semilla pulsa con vida y sientes que creces un centímetro."
T[555555]="Un amuleto cargado con el maná de magos muertos."
T[558601]="Te enseña a invocar esta montura."
T[558704]="Te enseña cómo invocar el Escudo Zandalari. Se muestra en tu espalda."
T[558798]="Te enseña cómo invocar esta montura. Esta montura puede volar."
T[558960]="<La poción está incompleta. Una nota pegada al costado enumera los ingredientes que Dulcinea ya ha comprado —tachados con pulcritud— y los que aún faltan por comprar: pétalos de flor de Elgris, concentrado de licor de Dun Kazad, zumo de calabaza y un globo ocular de murloc.>"
T[558970]="<Aunque este colgante no tiene un valor sentimental para ti, podría tenerlo para Thariel, el hermano de Elydna.>"
T[559143]="Una tira de carne que lleva mucho tiempo pudriéndose. El dulzor empalagoso de la decadencia entumece los sentidos."
T[559144]="Amalgama de buena carne, extraída del Osario de la luz de luna. Suelta podredumbre y apesta a carroña. Sin embargo, de algún modo, despierta el apetito de cada druida a tu alrededor."
T[559145]="Bendita amalgama de carne, humedecida y potenciada por el suave toque de la luna."
T[559377]="Te enseña a invocar este compañero."
T[559551]="Te enseña a invocar esta montura."
T[559851]="El diario de Lord Arathon, hijo de Servin Darengar y heredero de la familia.\n\nLas entradas en su interior son confusas, las anotaciones rozan lo críptico. Algunas páginas se parecen más a un libro de contabilidad que a un diario personal. Esta ambigüedad deliberada solo sirve para alimentar las sospechas. Las palabras 'Ealdir', 'pozo', 'cargamento' y 'cueva' aparecen una y otra vez."
T[560158]="\"Entré como una bola de demolición\""
T[650015]="Una guía desgastada por la naturaleza que aún conserva rastros de lo salvaje: agujas de pino, musgo y tierra."
T[650153]="Un pergamino etéreo que contiene mapas estelares que centellean con luz estelar real, cálido al tacto a pesar de su frialdad celestial."
T[663318]="Una copia de un diario escrito por Krelin, el Espadachín."
