T[824385]="Confieso que no pertenezco a ninguna filosofía. Pertenezco al mundo real. Pues la realidad no encaja en ninguna ideología. Tales cosas son abstracciones, consuelos que adoptamos por miedo a hacer preguntas sin la promesa de respuestas."
T[824396]="Yelmo usado por los fanáticos de Radiance Town. Un leve hormigueo se extiende a quienes se acercan. Aunque el origen del culto es misterioso, algunos susurran sobre un dios de la radiación, que apareció ante Su Radiante Majestad y le otorgó un propósito divino."
