T[1287330]="Otorga el alijo prestigioso más reciente disponible."
T[1297309]="¡Puede que a Harrison Jones le resulte útil!"
T[1303551]="¡Úsame!"
T[1303721]="La carne solo se cura en un foso de fuego arcano."
T[1303728]="Se sabe desde hace tiempo que las aguas termales tienen la combinación de calor y vapor adecuada para refinar este metal."
