T[1388227]="Antaño fabricado para proteger a su portador de cualquier daño, este collar ha sido corrompido por su proximidad a los Atal'ai."
T[1388369]="Un solo soplo y jurarás que el tiempo se ralentiza. Lo llaman trance de polvo. Yo lo llamo decisiones de vida lamentables."
T[1388372]="Perdido en una batalla, un abalorio de la codicia pirata olvidada."
T[1388374]="El ejemplar más exquisito."
T[1388379]="Puedes oír débilmente el mar cuando te acercas el oído."
T[1388479]="Imbuida con el poder resonante de los rituales de atadura de tierra de Martuk, esta capucha resuena con cada encantamiento, llamando a la roca y la piedra para que se levanten ante tu mandato."
T[1388543]="Las leyendas hablan de un pico solitario donde los relámpagos caen con la precisión de un reloj, una vez con cada luna llena. \n\nLa madera de la varita se tomó de un árbol alcanzado no una, sino dos veces; su poder está ahora entretejido en esta reliquia del antiguo linaje de los Thunderfalls."
T[1388546]="Tú... te... llevaste... ¿la vela?"
T[1388570]="Ojalá hubiera podido llegar a esa última isla. Los peces siempre son más grandes al otro lado."
T[1388578]="Estas notas describen la caída de un Drone hacia la locura mientras era objeto de experimentos."
T[1388633]="Snagglerspear es infame por usar este silbato en las cacerías de kodos, a menudo soplándolo para dar la señal a su manada para atacar."
T[1388794]="Un fragmento brillante, contaminado por energía de la Legión."
T[1388818]="Oye, mientras funcione"
T[1388920]="Al final, a veces el único plan que queda es huir."
T[1388927]="Endurecido por las llamas que antaño desafió."
T[1388967]="Imbuido de magia retorcida, el fragmento metálico late con un zumbido antiguo."
T[1389036]="Sostenido en tu mano, emite un suave zumbido, puntuado por un tenue chasquido. Quizá sea mejor dejarlo en paz."
T[1389048]="Eldara inscribía runas de Beth'Amara en cristales como este para proteger la ciudad, pero ni siquiera ese poder fue suficiente para salvarla del Sundering."
T[1389078]="Un manual maltrecho con secciones enteras tachadas y sustituidas por «-50 DKP!» en tinta roja y negrita."
T[1389109]="La semilla pulsa con vida y sientes que creces un centímetro."
T[1389901]="Confieso que no pertenezco a ninguna filosofía. Pertenezco al mundo real. Pues la realidad no encaja en ninguna ideología. Tales cosas son abstracciones, consuelos que adoptamos por miedo a hacer preguntas sin la promesa de respuestas."
T[1397884]="Una recompensa por completar misiones por todo Azeroth."
T[1397885]="Una recompensa por completar misiones por todo Azeroth"
T[1397886]="Una recompensa por completar misiones por todo Azeroth"
