T[1977451]="¡Haz clic derecho en mí! ¡Cualquier objeto para el que no tengas espacio se enviará a tu correo!\n\n|cFFFF5500IMPORTANTE:|r Solo recibes esto UNA VEZ. Asegúrate de abrirlo con el personaje que quieras que reciba las recompensas, ya que el |cFFFF5500contenido no se puede transferir ni reclamar.|r"
T[2000155]="Utilizado por los exploradores para fabricar diversos aumentos."
