T[2499004]="¡Haz clic derecho para explorar y comprar un paquete de apariencia de clase!"
T[2977350]="¡Haz clic derecho en mí! ¡Cualquier objeto para el que no tengas espacio se enviará a tu correo!"
T[2977352]="Un conjunto cosmético destinado a ser usado con Transfiguración. Puedes ver cómo son los conjuntos cosméticos en la Colección de vanidad. Estos pueden obtenerse de otros jugadores, la casa de subastas o la tienda de Ascension.\n\nEste conjunto tiene un par de opciones de transfiguración adicionales. ¡Asegúrate de probar las diferentes combinaciones y ver qué aspectos geniales puedes descubrir!"
T[2977353]="Contiene: 4x Bolsillo dimensional de Jaina (30 espacios)\n\n|cFFFF5500IMPORTANTE:|r Asegúrate de abrir esto en el personaje que quieras recibir las recompensas, ya que el |cFFFF5500contenido no se puede transferir ni reclamar.|r"
T[2977355]="¡Haz clic derecho en mí!\n\nRecibe:\n- Navaja del Arlequín de la Luna Negra\n- Verdugo del Arlequín de la Luna Negra\n- Hoja del Arlequín de la Luna Negra\n- Dado del Arlequín de la Luna Negra\n- Hacha del Arlequín de la Luna Negra\n- Protector del Arlequín de la Luna Negra\n- Cargador del Arlequín de la Luna Negra\n- Máscara del Arlequín de la Luna Negra"
T[2977357]="Contiene:\n\n- 10x Pergamino del Guardián: Golganneth\n- 10x Pergamino del Guardián: Norgannon\n- 10x Pergamino del Guardián: Khaz'goroth\n- 10x Pergamino del Guardián: Aggramar\n- 10x Pergamino del Guardián: Eonar\n- 5x Pergamino del Guardián: Altar de encantamiento\n- 5x Pergamino del Guardián: Firmeza\n- 5x Pergamino del Guardián: Caída de pluma\n- 5x Pergamino del Guardián: Corredor fantasma\n- 5x Pergamino del Guardián: Velocidad de recolección\n- 5x Pergamino del Guardián: Velocidad de fabricación\n\n|cFFFF5500IMPORTANTE:|r Asegúrate de abrir esto en el personaje que quieras recibir las recompensas, ya que el |cFFFF5500contenido no se puede transferir ni reclamar.|r"
T[2977359]="Contiene:\n\n- 6x Encantamiento místico: Especialización\n- Tomo de especialización II\n- Tomo de especialización III\n- Tomo de especialización IV\n- Tomo de especialización V\n- Tomo de especialización VI\n\n|cFFFF5500IMPORTANTE:|r Asegúrate de abrir esto en el personaje que quieras recibir las recompensas, ya que el |cFFFF5500contenido no se puede transferir ni reclamar.|r"
