T[515222]="Tempered in living flame."
T[515223]="Hardened by the flames it once defied."
T[515251]="Love and Heat go hand in hand."
T[515273]="Directly from Overseer Maltorius' tool collection. This has built the first Golems that started this excavation site. Sometimes it doubles down as more than a tool it seems."
T[515284]="The runes on the belt pulse with power from a long forgotten era."
T[515286]="Armor forged for a battle long past."
T[515292]="One man's trash..."
T[515365]="Vibrates with the same frequency as the Pylons."
T[515382]="This throwing weapon was once part of a Fab Four collection. Don’t let the pun fool you. It still packs a hit worthy of a worldwide tour."
T[515531]="Held in your grasp, it hums softly, punctuated by faint, crackle. Perhaps it's best left alone."
T[515537]="Increases Racing Speed by 300%"
T[515603]="Carved from the body of a Cliffwalker. Judging by the furbolgs' fate, the giants were none too happy about this."
T[515604]="A soft, melodic hum resonates from this ancient lyre. You can't help wondering how it's remained untouched for all these years..."
T[515608]="With some effort, you were finally able to remove this signet from the ancient statue."
T[515621]="An imitation of a much more powerful ring long since lost to time."
T[515623]="A metaphorical representation of Azshara's strength, its power seems to be quite literal as well."
T[515624]="Eldara inscribed Beth'Amara Runes onto crystals like this one to ward the city, yet even that power was not enough to save it from the Sundering."
T[515625]="Eldara inscribed Markri runes onto weapons like this one to defend the city from attackers. The enchantments animating it have long since faded, but it looks to function similarly to a modern crossbow."
T[515626]="These shoulderguards carry a faint echo of High Priest Zin-Malor’s power—an enigma that continues to baffle historians."
T[515629]="These lands bear the name of Her Radiance, and in her name shall we reclaim them!"
T[515634]="The runes engraved upon this staff still glow with the power of an ancient scribe who has long since vanished from Azeroth."
T[515676]="Goblin Engineering: Remember, it only has to work once!"
T[515681]="Forged from farmstead iron and blessed by faithful homesteaders"
T[515703]="Little remains of the body that once wore these pads, but the lingering magic woven into the tattered cloth still endures."
T[515720]="Scratched by teeth and claws, this humble ring tells the final tale of a hunter who never returned from the wild."
T[515733]="Resonates with the faint heartbeat of an ancient evil."
T[515737]="A battered handbook with entire sections scribbled out and replaced by ‘-50 DKP!’ in bold, red ink."
