T[559851]="The journal of Lord Arathon, son of Servin Darengar and heir to the family.\n\nThe entries within are muddled, the notations bordering on the cryptic. Some pages resemble a ledger more than a personal diary. This deliberate ambiguity only serves to fuel suspicion. The words 'Ealdir,' 'well,' 'shipment,' and 'cave' appear time and again."
T[560158]="\"I came in like a Wrecking ball\""
