T[2977352]="A Cosmetic set meant to be used with Transmogrification. You can see what Cosmetic Sets look like in the Vanity Collection. These can be obtained from other players, the auctionhouse, or the Ascension shop.\n\nThis set has a couple additional transmog options. Make sure to tryout the different combinations and see what cool looks you can discover!"
T[2977353]="Contains: 4x Jaina's Dimensional Pocket (30 Slot Bag)\n\n|cFFFF5500IMPORTANT:|r Make sure you open this on the character you want to receive the rewards, as the |cFFFF5500contents cannot be transferred or reclaimed.|r"
T[2977355]="Right click me!\n\nReceive:\n- Darkmoon Harlequin's Razor\n- Darkmoon Harlequin's Executioner\n- Darkmoon Harlequin's Blade\n- Darkmoon Harlequin's Die\n- Darkmoon Harlequin's Cleaver\n- Darkmoon Harlequin's Protector\n- Darkmoon Harlequin's Charger\n- Darkmoon Harlequin's Masque"
T[2977357]="Contains:\n\n- 10x Keeper's Scroll: Golganneth\n- 10x Keeper's Scroll: Norgannon\n- 10x Keeper's Scroll: Khaz'goroth\n- 10x Keeper's Scroll: Aggramar\n- 10x Keeper's Scroll: Eonar\n- 5x Keeper's Scroll: Enchanting Altar\n- 5x Keeper's Scroll: Steadfast\n- 5x Keeper's Scroll: Featherfall\n- 5x Keeper's Scroll: Ghost Runner\n- 5x Keeper's Scroll: Gathering Speed\n- 5x Keeper's Scroll: Crafting Speed\n\n|cFFFF5500IMPORTANT:|r Make sure you open this on the character you want to receive the rewards, as the |cFFFF5500contents cannot be transferred or reclaimed.|r"
T[2977359]="Contains:\n\n- 6x Mystic Enchanting: Specialization\n- Tome of Specialization II\n- Tome of Specialization III\n- Tome of Specialization IV\n- Tome of Specialization V\n- Tome of Specialization VI\n\n|cFFFF5500IMPORTANT:|r Make sure you open this on the character you want to receive the rewards, as the |cFFFF5500contents cannot be transferred or reclaimed.|r"
